def test_signature_over_another_report_returns_false(self):
    other_report = NonceLeakReport(
        (dataclasses.replace(self.leak, commitment=self.leak.commitment + 1),)
    )
    # The commitment change makes the receipts fail report verification;
    # a purely signature-level mismatch is covered by the synthetic case.
    self.assertFalse(
        verify_seal(
            ReportSeal(other_report, self.seal.signature), self.key
        )
    )

